namespace crowdsim::render {

namespace {

struct ShaderBlobs {
    const char* name;
    std::span<const std::uint8_t> dx11;
    std::span<const std::uint8_t> spirv;
    std::span<const std::uint8_t> glsl;
    std::span<const std::uint8_t> metal;
};

#if defined(CROWDSIM_SHADER_DX11)
#define CS_SHADER_BLOBS(n)                           \
    ShaderBlobs {                                    \
        #n, n##_dx11, n##_spirv, n##_glsl, n##_metal \
    }
#else
#define CS_SHADER_BLOBS(n)                     \
    ShaderBlobs {                              \
        #n, {}, n##_spirv, n##_glsl, n##_metal \
    }
#endif

std::span<const std::uint8_t> pick(const ShaderBlobs& blobs) {
    switch (bgfx::getRendererType()) {
        case bgfx::RendererType::Direct3D11:
        case bgfx::RendererType::Direct3D12:
            return blobs.dx11;
        case bgfx::RendererType::Vulkan:
            return blobs.spirv;
        case bgfx::RendererType::OpenGL:
            return blobs.glsl;
        case bgfx::RendererType::Metal:
            return blobs.metal;
        default:
            return {};
    }
}

bgfx::ShaderHandle createShader(const ShaderBlobs& blobs) {
    const auto blob = pick(blobs);
    if (blob.empty()) {
        return BGFX_INVALID_HANDLE;
    }
    // Static, immutable data: bgfx::makeRef avoids a copy.
    const bgfx::ShaderHandle handle =
        bgfx::createShader(bgfx::makeRef(blob.data(), static_cast<std::uint32_t>(blob.size())));
    bgfx::setName(handle, blobs.name);
    return handle;
}

bgfx::ProgramHandle createProgram(const ShaderBlobs& vs, const ShaderBlobs& fs) {
    const bgfx::ShaderHandle v = createShader(vs);
    const bgfx::ShaderHandle f = createShader(fs);
    if (!bgfx::isValid(v) || !bgfx::isValid(f)) {
        if (bgfx::isValid(v))
            bgfx::destroy(v);
        if (bgfx::isValid(f))
            bgfx::destroy(f);
        return BGFX_INVALID_HANDLE;
    }
    return bgfx::createProgram(v, f, /*destroyShaders=*/true);
}

}  // namespace

bgfx::ProgramHandle createEmbeddedProgram(EmbeddedProgram program) {
    switch (program) {
        case EmbeddedProgram::ImGui:
            return createProgram(CS_SHADER_BLOBS(vs_imgui), CS_SHADER_BLOBS(fs_imgui));
        case EmbeddedProgram::Agent:
            return createProgram(CS_SHADER_BLOBS(vs_agent), CS_SHADER_BLOBS(fs_agent));
        case EmbeddedProgram::Ground:
            return createProgram(CS_SHADER_BLOBS(vs_world), CS_SHADER_BLOBS(fs_ground));
        case EmbeddedProgram::Flat:
            return createProgram(CS_SHADER_BLOBS(vs_world), CS_SHADER_BLOBS(fs_flat));
        case EmbeddedProgram::Mesh:
            return createProgram(CS_SHADER_BLOBS(vs_mesh), CS_SHADER_BLOBS(fs_mesh));
        case EmbeddedProgram::Line:
            return createProgram(CS_SHADER_BLOBS(vs_line), CS_SHADER_BLOBS(fs_line));
        case EmbeddedProgram::Crowd:
            return createProgram(CS_SHADER_BLOBS(vs_crowd), CS_SHADER_BLOBS(fs_crowd));
        case EmbeddedProgram::CrowdShadow:
            return createProgram(CS_SHADER_BLOBS(vs_crowd), CS_SHADER_BLOBS(fs_shadow));
        case EmbeddedProgram::AgentShadow:
            return createProgram(CS_SHADER_BLOBS(vs_agent), CS_SHADER_BLOBS(fs_agent_shadow));
        case EmbeddedProgram::MeshShadow:
            return createProgram(CS_SHADER_BLOBS(vs_mesh), CS_SHADER_BLOBS(fs_mesh_shadow));
    }
    return BGFX_INVALID_HANDLE;
}

}  // namespace crowdsim::render
